from collections import deque
class Solution:
    def minimumCoins(self, prices):
        n = len(prices)
        f = [0] * (n + 1)
        dq = deque([0])
        for i in range(1, n + 1):
            lo = max(0, (i + 1) // 2 - 1)
            while dq and dq[0] < lo:
                dq.popleft()
            f[i] = f[dq[0]] + prices[dq[0]]
            g = f[i - 1] + prices[i - 1]
            while dq and f[dq[-1]] + prices[dq[-1]] >= g:
                dq.pop()
            dq.append(i - 1)
        return f[n]

