class Solution {
    public int minimumCoins(int[] prices) {
        int n = prices.length;
        int[] f = new int[n + 1];
        java.util.ArrayDeque<Integer> dq = new java.util.ArrayDeque<>();
        dq.add(0);
        for (int i = 1; i <= n; ++i) {
            int lo = Math.max(0, (i + 1) / 2 - 1);
            while (dq.peekFirst() < lo) dq.pollFirst();
            f[i] = f[dq.peekFirst()] + prices[dq.peekFirst()];
            int cand = i - 1, gv = f[cand] + prices[cand];
            while (!dq.isEmpty() && f[dq.peekLast()] + prices[dq.peekLast()] >= gv) dq.pollLast();
            dq.addLast(cand);
        }
        return f[n];
    }
}

